"""Paper 1 Section A multiple-choice questions (1 mark each).

Written in the three styles AQA uses in 7132/1 Section A:
  * single best answer
  * 'Statement 1 / Statement 2' true/false pairs
  * short data / calculation items
Every item carries an explanation of why the key is right and the distractors are wrong.
"""

ST_OPTS = [
    "Statement 1 is true. Statement 2 is true.",
    "Statement 1 is true. Statement 2 is false.",
    "Statement 1 is false. Statement 2 is true.",
    "Statement 1 is false. Statement 2 is false.",
]


def M(spec, question, options, answer, explanation):
    return {"spec": spec, "question": question, "options": options, "answer": answer, "explanation": explanation}


def S(spec, s1, t1, s2, t2, explanation, lead=""):
    answer = {(True, True): "A", (True, False): "B", (False, True): "C", (False, False): "D"}[(t1, t2)]
    q = (lead + "\n" if lead else "") + f"Statement 1: '{s1}'\nStatement 2: '{s2}'\nRead statements 1 and 2 and select the correct option."
    return M(spec, q, ST_OPTS, answer, explanation)


